const P=(ar,en)=>[ar,en];
const S={
 islam:{label:'The Metropolitan Museum of Art · Islamic chronology',url:'https://www.metmuseum.org/learn/educators/curriculum-resources/~/media/Files/Learn/For%20Educators/Publications%20for%20Educators/Islamic%20Teacher%20Resource/Introduction.pdf'},
 egypt:{label:'UCL · Chronology of Islamic Egypt',url:'https://www.ucl.ac.uk/museums-static/digitalegypt/chronology/islamic.html'},
 ayyubid:{label:'The Met · Ayyubid period',url:'https://www.metmuseum.org/essays/the-art-of-the-ayyubid-period-ca-1171-1260'},
 andalus:{label:'The Met · Umayyad Spain',url:'https://www.metmuseum.org/essays/the-art-of-the-umayyad-period-in-spain-711-1031'},
 nasrid:{label:'The Met · Nasrid period',url:'https://www.metmuseum.org/essays/the-art-of-the-nasrid-period-1232-1492'},
 druze:{label:'Encyclopedia of Religion · Druze',url:'https://www.encyclopedia.com/philosophy-and-religion/islam/islam/druze'},
 genizah:{label:'Cambridge University Library · Cairo Genizah',url:'https://www.lib.cam.ac.uk/collections/departments/taylor-schechter-genizah-research-unit/taylor-schechter-genizah-priceless'},
 maimonides:{label:'University of Cambridge · Maimonides manuscripts',url:'https://www.cam.ac.uk/stories/maimonides-fragments-discovered'},
 renaissance:{label:'The Met · Florence 1400–1600',url:'https://www.metmuseum.org/toah/ht/08/eustc.html'},
 humanism:{label:'Smarthistory · Humanism in Renaissance Italy',url:'https://smarthistory.org/humanism-renaissance-italy/'},
 reform:{label:'Johns Hopkins University Press · Reformation timeline',url:'https://timeline.press.jhu.edu/lut_reformation/1517-1617'},
 voyages:{label:'Royal Museums Greenwich · Exploration',url:'https://www.rmg.co.uk/collections/research-guides/research-guide-q1-exploration-discovery'},
 gama:{label:'The Mariners’ Museum · Vasco da Gama',url:'https://exploration.marinersmuseum.org/subject/vasco-da-gama/'},
 france:{label:'Musée Carnavalet · Revolution and nineteenth century',url:'https://www.carnavalet.paris.fr/en/le-nouveau-parcours'},
 napoleon:{label:'Palace of Versailles · Revolution to interwar period',url:'https://en.chateauversailles.fr/discover/resources/versailles-french-revolution-interwar-period'},
 coup:{label:'Fondation Napoléon · 1799 coup chronology',url:'https://www.napoleon.org/en/enseignants/documents/1799-le-coup-detat-du-18-brumaire-le-general-napoleon-bonaparte-prend-le-pouvoir-cours/'},
 steam:{label:'Science Museum · James Watt’s condenser',url:'https://blog.sciencemuseum.org.uk/james-watt-and-the-separate-condenser/'},
 industrial:{label:'Science Museum · Steam through the centuries',url:'https://blog.sciencemuseum.org.uk/steaming-through-the-centuries/'},
 national:{label:'OpenStax, Rice University · Nationalism and the political order',url:'https://openstax.org/books/world-history-volume-2/pages/7-4-nationalism-liberalism-conservatism-and-the-political-order'},
 berlin:{label:'German Federal Foreign Office · Berlin Conference archive',url:'https://archiv.diplo.de/arc-en/the-political-archive/general-act-2684414'},
 colonial:{label:'University of Potsdam · Berlin Africa Conference',url:'https://www.uni-potsdam.de/en/botanischer-garten/unser-garten/kolonialismus/berlin-afrika-konferenz'},
 ww1:{label:'National WWI Museum · Key dates',url:'https://www.theworldwar.org/learn/about-wwi/key-dates'},
 peace:{label:'National WWI Museum · Peace treaties',url:'https://www.theworldwar.org/learn/educator-resource/peace-treaties-ended-first-world-war'},
 paris:{label:'US Office of the Historian · Paris Peace Conference',url:'https://history.state.gov/milestones/1914-1920/paris-peace'},
 tanzimat:{label:'Cambridge University Press · Ottoman reform 1839–1907',url:'https://www.cambridge.org/core/books/abs/workers-and-peasants-in-the-modern-middle-east/ottoman-reform-and-european-imperialism-18391907/CB0C0938A39820F7BA88C52FC2950B45'},
 middle:{label:'Imperial War Museums · First World War oral histories',url:'https://www.iwm.org.uk/podcasts/voices-of-the-first-world-war'}
};
export const HISTORY_LESSONS=[];
const E=(year,ar,en,da,de,date)=>({year,date:date||P(String(year),String(year)),title:P(ar,en),detail:P(da,de)});
function add(id,title,titleEn,kind,rule,events,causes,effects,sources,analysis){
 const lesson={id,title,arTitle:title,titleEn,kind,rule,events:events.sort((a,b)=>a.year-b.year),causes,effects,sources:sources.map(s=>S[s]),question:analysis.prompt,questions:[]};
 // Every question is anchored to this lesson's named events, not a generic history template.
 lesson.questions=lesson.events.slice(0,3).map((e,i)=>{const dates=lesson.events.map(x=>x.date);let options=[e.date,...dates.filter(x=>x[1]!==e.date[1])].slice(0,3);if(options.length<3)options.push(P(String(e.year+25),String(e.year+25)));return {prompt:P(`متى حدث «${e.title[0]}»؟`,`When did “${e.title[1]}” take place?`),options,answer:0,explanation:P(`${e.date[0]}: ${e.detail[0]}`,`${e.date[1]}: ${e.detail[1]}`)};});
 lesson.questions.push({prompt:P('أي هذه الأحداث وقع أولًا؟','Which of these events happened first?'),options:lesson.events.slice(0,3).map(e=>e.title),answer:0,explanation:P(`${lesson.events[0].title[0]} (${lesson.events[0].date[0]}) يسبق الحدثين الآخرين؛ السبق الزمني وحده لا يثبت السببية.`,`${lesson.events[0].title[1]} (${lesson.events[0].date[1]}) precedes the other two; chronological order alone does not establish causation.`)},analysis);
 HISTORY_LESSONS.push(lesson);
}
const A=(ar,en,correct,wrong1,wrong2,explanation)=>({prompt:P(ar,en),options:[correct,wrong1,wrong2],answer:0,explanation});
add('umayyad','الدولة الأموية','Umayyad Caliphate','timeline',P('حكم الأمويون من دمشق بين 661 و750. نميّز بين توسع الدولة وتطور إدارتها؛ انتقال الحكم لا يعني اختفاء المجتمع أو ثقافته.','The Umayyads ruled from Damascus between 661 and 750. Territorial expansion and administrative change are different processes; a new dynasty does not erase society.'),[
 E(661,'بداية الخلافة الأموية','Umayyad caliphate begins','أصبح معاوية خليفة واتخذ دمشق مركزًا للحكم.','Muawiya became caliph, with Damascus as the political centre.'),E(691,'قبة الصخرة','Dome of the Rock','اكتمل البناء نحو 691–692 في عهد عبد الملك.','The building was completed around 691–692 under Abd al-Malik.',P('نحو 691–692','c. 691–692')),E(750,'الثورة العباسية','Abbasid revolution','انتهى الحكم الأموي في المشرق؛ استمر فرع أموي لاحقًا في الأندلس.','Umayyad rule in the east ended; a later branch ruled in al-Andalus.')],[P('التنافس على الخلافة وتنظيم أراضٍ واسعة','Competition for the caliphate and administration of extensive territories')],[P('ازدياد دور العربية في الإدارة والعملة','A growing role for Arabic in administration and coinage')],['islam'],A('ما عاصمة الأمويين في المشرق؟','Which city was the eastern Umayyad capital?',P('دمشق','Damascus'),P('بغداد','Baghdad'),P('القاهرة','Cairo'),P('كان مركز الحكم في دمشق، قبل انتقال المركز العباسي إلى العراق.','Damascus was the political centre before Abbasid power shifted to Iraq.')));
add('abbasid','الدولة العباسية','Abbasid Caliphate','society',P('انتقل مركز الخلافة إلى العراق. ازدهرت مجالات معرفة وتجارة، مع تغير نفوذ الخلفاء عبر القرون؛ لا نعامل خمسة قرون كفترة ثابتة.','The centre of the caliphate moved to Iraq. Scholarship and commerce flourished in different settings, while caliphal power changed across five centuries.'),[E(750,'قيام الدولة العباسية','Abbasid rule begins','حل العباسيون محل الأمويين في المشرق.','The Abbasids replaced eastern Umayyad rule.'),E(762,'تأسيس بغداد','Foundation of Baghdad','أسس المنصور مدينة جديدة لتكون مركزًا للحكم.','Al-Mansur founded a new political capital.'),E(1258,'سقوط بغداد','Fall of Baghdad','أنهى الغزو المغولي الخلافة العباسية في بغداد.','The Mongol conquest ended the Baghdad caliphate.')],[P('معارضة الحكم الأموي وتحالفات الثورة','Opposition to Umayyad rule and revolutionary alliances')],[P('نمو بغداد مركزًا سياسيًا وفكريًا وتجاريًا','Baghdad developed as a political, intellectual and commercial centre')],['islam'],A('ماذا يميّز سنة 762 في التاريخ العباسي؟','What distinguishes 762 in Abbasid history?',P('تأسيس بغداد','Foundation of Baghdad'),P('سقوط بغداد بيد المغول','Mongol conquest of Baghdad'),P('قيام الدولة المملوكية','Foundation of the Mamluk state'),P('أسس المنصور بغداد سنة 762؛ الغزو المغولي جاء بعد ذلك بقرون.','Al-Mansur founded Baghdad in 762; the Mongol conquest came centuries later.')));
add('andalus','الأندلس','Al-Andalus','routes',P('الأندلس اسم لأراضٍ إيبيرية تحت حكم إسلامي بحدود متغيرة، لا لدولة واحدة ثابتة. نتتبع قرطبة وغرناطة والتبادل الثقافي والصراع معًا.','Al-Andalus describes changing Muslim-ruled territories in Iberia, not one unchanging state. Córdoba and Granada reveal both cultural exchange and conflict.'),[E(711,'عبور إلى شبه الجزيرة الإيبيرية','Crossing into Iberia','دخلت قوات من شمال إفريقيا وبدأ الحكم الإسلامي في أجزاء من شبه الجزيرة.','Forces crossed from North Africa, beginning Muslim rule in parts of Iberia.'),E(756,'إمارة قرطبة','Emirate of Córdoba','أسس عبد الرحمن الأول إمارة أموية مستقلة.','Abd al-Rahman I established an independent Umayyad emirate.'),E(1492,'تسليم غرناطة','Surrender of Granada','انتهى حكم بني نصر في غرناطة.','Nasrid rule in Granada ended.')],[P('انتقال جيوش وسكان وأفكار عبر المتوسط','Movement of armies, people and ideas across the Mediterranean')],[P('تراث في العمارة والعلوم والأدب مع تغير الحكام والحدود','Architectural, scholarly and literary legacies amid changing rulers and borders')],['andalus','nasrid'],A('لماذا لا نرسم حدود الأندلس كأنها ثابتة؟','Why should al-Andalus not be shown with fixed borders?',P('لأن رقعتها وسلالاتها الحاكمة تغيرت','Its territory and dynasties changed'),P('لأنها كانت مدينة واحدة فقط','It was only one city'),P('لأن قرطبة وغرناطة مدينة واحدة','Córdoba and Granada were one city'),P('امتد تاريخ الأندلس قرونًا شهدت توسعًا وتراجعًا ودولًا متعددة.','Its centuries of history included expansion, contraction and several states.')));
add('medieval-europe','أوروبا في العصور الوسطى','Europe in the Middle Ages','society',P('العصور الوسطى تقسيم تقريبي، وليست عصرًا بلا علم. اختلفت المدن والأرياف وأنظمة السلطة، وتداخل الدين والتجارة والمعرفة والحرب.','The Middle Ages are an approximate period, not an age without learning. Towns, rural communities and political systems differed; religion, trade, learning and war interacted.'),[E(476,'نهاية الإمبراطورية الرومانية الغربية','End of the Western Roman Empire','عُزل رومولوس أوغستولوس؛ استمرت الإمبراطورية الرومانية الشرقية.','Romulus Augustulus was deposed; the Eastern Roman Empire continued.'),E(800,'تتويج شارلمان','Charlemagne crowned emperor','توّج البابا شارلمان في روما.','The pope crowned Charlemagne in Rome.'),E(1347,'وصول الموت الأسود إلى أوروبا','Black Death reaches Europe','بدأ انتشار وباء أحدث تغيرات سكانية واقتصادية واسعة.','An epidemic began spreading with major demographic and economic consequences.')],[P('تغير السلطة بعد انهيار الحكم الروماني الغربي','Changing power after the collapse of western Roman government')],[P('تطور الممالك والمدن والجامعات بطرق متفاوتة','Kingdoms, towns and universities developed unevenly')],['national'],A('ما الذي استمر بعد سنة 476؟','What continued after 476?',P('الإمبراطورية الرومانية الشرقية','The Eastern Roman Empire'),P('حكم رومولوس أوغستولوس في الغرب','Romulus Augustulus’s rule in the west'),P('الدولة القومية الألمانية الحديثة','The modern German nation-state'),P('476 علامة تقليدية لنهاية الغرب الروماني، لا لنهاية كل المؤسسات أو الإمبراطورية الشرقية.','476 conventionally marks the western empire’s end, not the disappearance of every institution or the eastern empire.')));
add('crusades','الحملات الصليبية','Crusades','routes',P('كانت الحملات الصليبية حملات عسكرية ذات دوافع دينية وسياسية ومادية متعددة. اختلفت المشاركات والنتائج؛ ندرس المدنيين والتبادل أيضًا، لا المعارك وحدها.','The Crusades were military campaigns with religious, political and material motives. Participants and outcomes differed; civilian experiences and exchange matter alongside battles.'),[E(1095,'دعوة كليرمون','Call at Clermont','دعا البابا أوربان الثاني إلى الحملة الأولى.','Pope Urban II called for the First Crusade.'),E(1099,'استيلاء الصليبيين على القدس','Crusaders capture Jerusalem','استولى جيش الحملة الأولى على المدينة وارتكب مذابح.','The First Crusade captured the city and committed massacres.'),E(1187,'حطين واستعادة القدس','Hattin and recapture of Jerusalem','انتصرت قوات صلاح الدين في حطين ثم استعادت القدس.','Saladin’s forces won at Hattin and subsequently recovered Jerusalem.')],[P('دعوات دينية وصراعات على الأرض والسلطة','Religious appeals and struggles over territory and power')],[P('حروب ودول صليبية واتصالات مستمرة في شرق المتوسط','Wars, crusader states and continuing eastern Mediterranean contacts')],['ayyubid'],A('أي وصف للدوافع أدق؟','Which account of motives is more accurate?',P('تداخلت دوافع دينية وسياسية ومادية','Religious, political and material motives interacted'),P('كانت جميع الحملات بلا دوافع دينية','Every campaign lacked religious motives'),P('شارك الجميع للسبب نفسه حصرًا','Everyone participated for exactly the same reason'),P('تعدد المشاركين والسياقات يمنع اختزال كل الحملات في سبب واحد.','Different participants and contexts prevent reducing every campaign to one motive.')));
add('fatimid','الدولة الفاطمية','Fatimid Caliphate','timeline',P('نشأت الخلافة الفاطمية في شمال إفريقيا ثم اتخذت القاهرة مركزًا. تنافست مع العباسيين، وارتبط تاريخها بتجارة المتوسط والبحر الأحمر.','The Fatimid caliphate began in North Africa and later centred on Cairo. It rivalled the Abbasids and connected Mediterranean and Red Sea trade.'),[E(909,'قيام الخلافة الفاطمية','Fatimid caliphate founded','بدأ الحكم الفاطمي في شمال إفريقيا.','Fatimid rule began in North Africa.'),E(969,'السيطرة على مصر وتأسيس القاهرة','Conquest of Egypt and foundation of Cairo','أسس الفاطميون القاهرة بعد السيطرة على مصر.','The Fatimids founded Cairo after taking Egypt.'),E(1171,'نهاية الخلافة الفاطمية','End of the Fatimid caliphate','أنهى صلاح الدين الخلافة الفاطمية في مصر.','Saladin ended the Fatimid caliphate in Egypt.')],[P('بناء خلافة منافسة للعباسيين','Building a rival caliphate to the Abbasids')],[P('صعود القاهرة مركزًا للحكم والتجارة','Cairo became a political and commercial centre')],['egypt'],A('أي ترتيب صحيح للمراكز الفاطمية؟','Which sequence of Fatimid centres is correct?',P('شمال إفريقيا ثم مصر','North Africa, then Egypt'),P('مصر ثم بغداد','Egypt, then Baghdad'),P('الأندلس ثم باريس','Al-Andalus, then Paris'),P('بدأت الدولة سنة 909 في شمال إفريقيا، وانتقل مركزها إلى مصر لاحقًا.','The state began in North Africa in 909 and later centred on Egypt.')));
add('ayyubid','الدولة الأيوبية','Ayyubid state','timeline',P('أسس صلاح الدين الحكم الأيوبي، وشملت الدولة مراكز متعددة وأفرادًا من أسرته. انتهى الحكم الأيوبي في مصر قبل انتهاء بعض فروعه في الشام.','Saladin established Ayyubid rule, with several centres governed by members of his family. Rule in Egypt ended before some Syrian branches.'),[E(1171,'بداية الحكم الأيوبي في مصر','Ayyubid rule in Egypt begins','أنهى صلاح الدين الحكم الفاطمي.','Saladin ended Fatimid rule.'),E(1187,'معركة حطين','Battle of Hattin','غيّر الانتصار الأيوبي ميزان القوة مع الدول الصليبية.','An Ayyubid victory changed the balance with the crusader states.'),E(1250,'انتقال الحكم في مصر إلى المماليك','Mamluk takeover in Egypt','انتهى الحكم الأيوبي في مصر، لا جميع الفروع في اللحظة نفسها.','Ayyubid rule ended in Egypt, not in every branch simultaneously.')],[P('تراجع السلطة الفاطمية وصعود صلاح الدين','Weakening Fatimid authority and Saladin’s rise')],[P('تعزيز مراكز الحكم والدفاع في مصر والشام','Strengthening political and defensive centres in Egypt and Syria')],['ayyubid'],A('ما الدقة الضرورية عند ذكر 1250؟','What qualification is needed for 1250?',P('انتهى الحكم الأيوبي في مصر','Ayyubid rule ended in Egypt'),P('انتهت كل فروع الأيوبيين في العالم فورًا','Every Ayyubid branch ended immediately'),P('بدأ الحكم الفاطمي في القاهرة','Fatimid rule began in Cairo'),P('تختلف نهاية السلالة بين مصر ومناطق حكم فروعها.','The dynasty’s end differed between Egypt and territories ruled by its branches.')));
add('mamluk','الدولة المملوكية','Mamluk Sultanate','timeline',P('حكم سلاطين المماليك مصر والشام ضمن نظام نخب عسكرية. ارتبطت قوتهم بالدفاع والتجارة والمؤسسات العمرانية والدينية.','Mamluk sultans governed Egypt and Syria through military elites. Their power involved defence, commerce and urban and religious institutions.'),[E(1250,'قيام السلطنة في مصر','Sultanate founded in Egypt','انتقل الحكم من الأيوبيين إلى المماليك.','Power passed from the Ayyubids to the Mamluks.'),E(1260,'عين جالوت','Battle of Ain Jalut','هزمت قوات المماليك جيشًا مغوليًا في بلاد الشام.','Mamluk forces defeated a Mongol army in the Levant.'),E(1517,'الفتح العثماني لمصر','Ottoman conquest of Egypt','انتهت السلطنة المستقلة مع استمرار نخب مملوكية لاحقًا.','The independent sultanate ended, though Mamluk elites continued afterward.')],[P('صعود القادة العسكريين في الدولة الأيوبية','The rise of military commanders under the Ayyubids')],[P('مركزية القاهرة وبناء منشآت ورعاية طرق التجارة','Cairo’s prominence, construction and protection of trade routes')],['egypt','islam'],A('ماذا انتهى سنة 1517؟','What ended in 1517?',P('السلطنة المملوكية المستقلة','The independent Mamluk sultanate'),P('وجود كل المماليك ونخبهم','The existence of all Mamluks and their elites'),P('الحكم العثماني في مصر','Ottoman rule in Egypt'),P('نهاية دولة لا تعني اختفاء كل فئاتها الاجتماعية والسياسية.','The end of a state does not mean every social or political group disappeared.')));
add('druze','الدروز في العصور الوسطى','Druze in the Middle Ages','society',P('تبلورت الدعوة الدرزية في البيئة الفاطمية في القرن الحادي عشر. نميز تاريخ ظهورها عن حياة الجماعات المحلية اللاحقة؛ لا نمثل الدروز كتجربة سياسية واحدة ثابتة.','The Druze movement emerged in the Fatimid setting of the eleventh century. Its emergence differs from the later lives of local communities; Druze political experiences were not uniform.'),[E(1017,'بداية الدعوة العلنية','Public preaching begins','ظهرت الدعوة في القاهرة ضمن سياق الحكم الفاطمي.','The movement began public preaching in Fatimid Cairo.'),E(1021,'اختفاء الحاكم بأمر الله','Disappearance of al-Hakim','تبعت اختفاءه مرحلة صعبة للمؤمنين بالدعوة.','His disappearance was followed by a difficult period for followers.'),E(1043,'إغلاق باب الدعوة','Closure of the mission','ارتبطت المرحلة بانتهاء قبول المنضمين الجدد إلى الجماعة.','This stage is associated with the end of admission of new converts.')],[P('نقاشات دينية في البيئة الفاطمية','Religious debates in the Fatimid setting')],[P('استمرار جماعات محلية ذات هوية دينية مميزة في بلاد الشام','Continuing local communities with a distinct religious identity in the Levant')],['druze'],A('أي استنتاج نتجنبه من هذا الخط الزمني؟','Which conclusion should this timeline NOT support?',P('أن كل الجماعات الدرزية عاشت الظروف نفسها','That all Druze communities experienced identical conditions'),P('أن الدعوة ظهرت في القرن الحادي عشر','That the movement emerged in the eleventh century'),P('أن السياق الفاطمي مهم لفهم النشأة','That the Fatimid setting matters for its emergence'),P('تختلف الظروف المحلية والعلاقات السياسية؛ الهوية المشتركة لا تعني تجربة واحدة.','Local conditions and political relationships varied; shared identity does not imply a single experience.')));
add('medieval-jews','اليهود في البلدان الإسلامية في العصور الوسطى','Jews in medieval Islamic lands','society',P('تُظهر وثائق الجنيزة التجارة والأسرة والطب والتعليم. اختلفت أوضاع اليهود بحسب المكان والحاكم والزمن؛ حالة ابن ميمون نافذة محددة، لا وصف لكل الجماعات.','Genizah documents illuminate trade, family, medicine and learning. Jewish conditions varied by place, ruler and period; Maimonides is one case, not a description of every community.'),[E(1135,'ولادة ابن ميمون في قرطبة','Maimonides born in Córdoba','يُؤرَّخ ميلاده بنحو 1135 أو 1138 في بعض الدراسات.','His birth is dated around 1135 or 1138 in different studies.',P('نحو 1135–1138','c. 1135–1138')),E(1168,'حياته في مصر','His life in Egypt','تؤرّخ مكتبة كامبريدج مخطوطاته المصرية من هذه المرحلة إلى وفاته.','Cambridge dates his Egyptian manuscript activity from this period to his death.'),E(1204,'وفاة ابن ميمون','Death of Maimonides','بقيت كتاباته الطبية والفلسفية ورسائله مصادر للدراسة.','His medical and philosophical writings and letters remain historical evidence.')],[P('شبكات تجارة ومعرفة متعددة اللغات','Multilingual networks of commerce and learning')],[P('وثائق تكشف الحياة اليومية إلى جانب أعمال العلماء','Documents revealing daily life alongside scholarly works')],['genizah','maimonides'],A('لماذا نقرأ رسائل الجنيزة إلى جانب سير العلماء؟','Why read Genizah letters alongside scholars’ biographies?',P('لفهم الأسرة والعمل والتجارة والحياة اليومية','To understand family, work, trade and daily life'),P('لإثبات أن كل اليهود عاشوا التجربة نفسها','To prove all Jews shared identical experiences'),P('لأنها تلغي الحاجة إلى تحديد المكان والزمن','Because they remove the need to identify place and period'),P('توسّع الوثائق أنواع الأصوات والأدلة، ولا تسمح بالتعميم على كل البلاد والعصور.','Documents broaden the voices and evidence without justifying universal claims across places and periods.')));
add('renaissance','عصر النهضة','Renaissance','society',P('النهضة تحول تدريجي في الفن والتعلم، بدأ في مدن إيطالية وامتد بطرق مختلفة. ساعدت الرعاية والثروة الحضرية ودراسة التراث القديم، ولم يتوقف الاهتمام بالدين.','The Renaissance was a gradual change in art and learning, beginning in Italian cities and spreading unevenly. Patronage, urban wealth and classical study mattered; religious interests continued.'),[E(1400,'ازدهار النهضة الإيطالية المبكرة','Early Italian Renaissance flourishes','تاريخ تقريبي لمرحلة، لا سنة بدء مفاجئ.','An approximate marker for a period, not a sudden starting year.',P('نحو 1400','c. 1400')),E(1435,'ألبرتي يكتب عن التصوير','Alberti writes On Painting','ناقش النظرية والمنظور وأهداف الرسم.','He discussed theory, perspective and the purposes of painting.'),E(1500,'مرحلة النهضة العليا','High Renaissance period','برزت أعمال فنية كبرى مع استمرار تنوع المدارس.','Major works appeared amid continuing artistic diversity.',P('نحو 1500','c. 1500'))],[P('رعاية الفنون وتداول النصوص القديمة','Art patronage and circulation of classical texts')],[P('تطور المنظور وصور الأفراد ودراسة العمارة القديمة','Developments in perspective, portraiture and study of ancient architecture')],['renaissance','humanism'],A('كيف ساعدت رعاية الفنون على النهضة؟','How did patronage support the Renaissance?',P('وفرت المال والتكليفات للفنانين','It provided funding and commissions'),P('منعت جميع الموضوعات الدينية','It banned every religious subject'),P('جعلت كل المدن تتطور في السنة نفسها','It made all cities change in the same year'),P('موّلت مؤسسات وأفراد أعمالًا جديدة؛ النهضة بقيت متعددة المراكز والإيقاعات.','Institutions and individuals funded new works; change still varied across centres and periods.')));
add('humanism','الإنسانية Humanism','Renaissance humanism','society',P('الإنسانية هنا منهج تعلم يدرس اللغة والبلاغة والتاريخ والشعر والفلسفة الأخلاقية بالعودة إلى النصوص القديمة. لا تعني مجرد اللطف، ولا تعني بالضرورة رفض الدين.','Humanism here is an educational approach studying language, rhetoric, history, poetry and moral philosophy through classical texts. It is not simply kindness or necessarily rejection of religion.'),[E(1300,'جذور الحركة الإنسانية الإيطالية','Roots of Italian humanism','نمت إعادة قراءة التراث الكلاسيكي في القرون اللاحقة.','Renewed reading of classical literature developed over subsequent centuries.',P('القرن الرابع عشر','14th century')),E(1400,'البحث عن المخطوطات','Search for manuscripts','بحث إنسانيون في المكتبات عن نصوص قديمة.','Humanists searched libraries for ancient texts.',P('أوائل القرن الخامس عشر','Early 15th century')),E(1450,'انتشار الطباعة الأوروبية','European printing expands','ساعدت الطباعة بالحروف المتحركة على تداول النصوص.','Movable-type printing helped texts circulate.',P('منتصف القرن الخامس عشر','Mid-15th century'))],[P('الرغبة في قراءة النصوص الأصلية وتعليم المواطن','Interest in original texts and civic education')],[P('توسيع التعليم ونقد النصوص والتأثير في الفن','Developments in education, textual criticism and art')],['humanism','renaissance'],A('أي نشاط يمثل المنهج الإنساني؟','Which activity represents humanist learning?',P('مقارنة مخطوطات قديمة ودراسة لغتها','Comparing ancient manuscripts and studying their language'),P('رفض قراءة جميع الكتب القديمة','Refusing all ancient books'),P('حصر التعلم في التدريب العسكري','Restricting education to military training'),P('اهتم الإنسانيون باللغة والنصوص والتربية، مع اختلاف توجهاتهم الدينية.','Humanists studied language, texts and education while differing in religious outlook.')));
add('reformation','الإصلاح الديني','Reformation','cause',P('نشأ الإصلاح من خلافات حول العقيدة وسلطة الكنيسة وممارساتها. ساعدت الطباعة والسياسة في انتشاره؛ لم تكن أوروبا الكاثوليكية والبروتستانتية كتلتين متجانستين.','The Reformation involved disputes about doctrine, church authority and practices. Printing and politics helped it spread; neither Catholic nor Protestant Europe was uniform.'),[E(1517,'أطروحات لوثر الخمس والتسعون','Luther’s Ninety-Five Theses','اعترض لوثر على ممارسات مرتبطة بصكوك الغفران.','Luther challenged practices concerning indulgences.'),E(1521,'لوثر ومجمع فورمس','Luther at the Diet of Worms','رفض لوثر التراجع عن مواقفه الأساسية.','Luther refused to retract his central positions.'),E(1555,'صلح أوغسبورغ','Peace of Augsburg','اعترف بوضع اللوثرية ضمن تسوية محدودة في الإمبراطورية الرومانية المقدسة.','It recognized Lutheranism in a limited Holy Roman Empire settlement.')],[P('الجدل حول الغفران والسلطة الدينية','Debate over indulgences and religious authority')],[P('تعدد الكنائس وصراعات وتسويات دينية وسياسية','New churches, conflicts and religious-political settlements')],['reform'],A('هل منح صلح أوغسبورغ حرية دينية شاملة للجميع؟','Did the Peace of Augsburg grant universal religious freedom?',P('لا؛ كانت تسوية محدودة بين الكاثوليكية واللوثرية','No; it was a limited Catholic–Lutheran settlement'),P('نعم؛ شمل كل الأديان بالتساوي','Yes; it included every religion equally'),P('نعم؛ ألغى كل سلطة سياسية','Yes; it abolished political authority'),P('يجب التمييز بين اعتراف قانوني محدد ومفهوم الحرية الدينية الشاملة.','A specific legal recognition differs from universal religious freedom.')));
add('exploration','الاكتشافات الجغرافية','Oceanic exploration and encounters','routes',P('تصف عبارة «الاكتشافات» منظور الرحلات الأوروبية، لا غياب سكان أو معرفة سابقة. ربطت الرحلات شبكات بحرية، وارتبط توسعها بالتجارة والغزو والاستعمار.','“Discovery” describes a European voyage perspective, not the absence of inhabitants or earlier knowledge. Voyages connected maritime networks and became linked to trade, conquest and colonization.'),[E(1488,'دياز يدور حول رأس الرجاء الصالح','Dias rounds the Cape','فتح الالتفاف طريقًا بحريًا أوروبيًا نحو المحيط الهندي.','Rounding southern Africa opened a European maritime approach to the Indian Ocean.'),E(1492,'وصول كولومبوس إلى الكاريبي','Columbus reaches the Caribbean','وصل إلى أراضٍ مأهولة بشعوب أصلية.','He reached lands inhabited by Indigenous peoples.'),E(1498,'دا غاما يصل إلى الهند','Da Gama reaches India','وصل عبر طريق حول إفريقيا إلى شبكات تجارة قائمة.','He reached existing trading networks via a route around Africa.')],[P('السعي لطرق تجارة ورعاية ملكية وخبرة بحرية','The search for trade routes, royal backing and maritime experience')],[P('تبادل عالمي متزايد واستعمار وأضرار جسيمة للسكان الأصليين','Increasing global exchange, colonization and severe harm to Indigenous peoples')],['voyages','gama'],A('ما الخطأ في القول إن كولومبوس وصل إلى أرض بلا سكان؟','What is wrong with saying Columbus reached an empty land?',P('كانت شعوب أصلية تعيش هناك','Indigenous peoples already lived there'),P('لم يصل أي إنسان إلى الكاريبي','No human reached the Caribbean'),P('كانت الكاريبي جزءًا من أوروبا','The Caribbean was part of Europe'),P('وصول الأوروبيين ليس بداية تاريخ الأمريكتين أو سكانهما.','European arrival is not the beginning of the Americas’ history or inhabitants.')));
add('columbus','اكتشاف أمريكا','Columbus and the Americas','routes',P('نستخدم العنوان المدرسي مع توضيح أن الأمريكتين مأهولتان منذ آلاف السنين. كانت رحلة 1492 بداية اتصال أوروبي مستمر تبعه استعمار، وليست اكتشاف أرض خالية.','We retain the curriculum title while recognizing that people had inhabited the Americas for millennia. The 1492 voyage began sustained European contact followed by colonization, not discovery of an empty land.'),[E(1492,'الرحلة الأولى إلى الكاريبي','First Caribbean voyage','وصل كولومبوس معتقدًا أنه اقترب من آسيا.','Columbus arrived believing he had approached Asia.'),E(1493,'الرحلة الثانية','Second voyage','جاءت بعثة أكبر مرتبطة بإقامة الاستعمار الإسباني.','A larger expedition was associated with Spanish colonization.'),E(1502,'بداية الرحلة الرابعة','Fourth voyage begins','استكشف سواحل في أمريكا الوسطى.','He explored parts of the Central American coast.')],[P('طلب طريق غربي إلى آسيا بتمويل ملكي إسباني','Seeking a westward route to Asia with Spanish royal funding')],[P('استعمار وعمل قسري وانتقال أمراض ومحاصيل وحيوانات','Colonization, forced labour and movement of diseases, crops and animals')],['voyages'],A('أي وصف أدق لرحلة 1492؟','Which description of the 1492 voyage is more accurate?',P('وصول أوروبي إلى الكاريبي المأهولة','European arrival in an inhabited Caribbean'),P('أول وجود بشري في الأمريكتين','The first human presence in the Americas'),P('وصول إلى الهند حول إفريقيا','Arrival in India by rounding Africa'),P('كانت الجزر مأهولة؛ كولومبوس ظن أنه وصل قرب آسيا.','The islands were inhabited; Columbus believed he had reached near Asia.')));
add('cape','رأس الرجاء الصالح','Cape of Good Hope route','routes',P('يميز هذا الدرس بين الدوران حول جنوب إفريقيا والوصول إلى الهند. استُخدمت المعرفة الملاحية وشبكات المحيط الهندي القائمة؛ لم يبدأ تاريخ المنطقة بوصول البرتغاليين.','This lesson distinguishes rounding southern Africa from reaching India. Voyages used navigational knowledge and existing Indian Ocean networks; regional history did not begin with the Portuguese.'),[E(1488,'دياز يدور حول الرأس','Dias rounds the Cape','برهن على اتصال الطريق البحري حول جنوب إفريقيا بالمحيط الهندي.','His voyage demonstrated the sea connection around southern Africa to the Indian Ocean.'),E(1497,'انطلاق رحلة دا غاما','Da Gama departs','غادرت بعثته البرتغال نحو الهند.','His expedition left Portugal for India.'),E(1498,'وصول دا غاما إلى كاليكوت','Da Gama reaches Calicut','وصل إلى ميناء هندي ضمن شبكة تجارة نشطة.','He reached an Indian port within an active trade network.')],[P('البحث البرتغالي عن طريق بحري لتجارة آسيا','Portuguese efforts to establish a sea route to Asian trade')],[P('زيادة التدخل البرتغالي في تجارة المحيط الهندي','Growing Portuguese intervention in Indian Ocean trade')],['gama'],A('من وصل إلى الهند في 1498؟','Who reached India in 1498?',P('فاسكو دا غاما','Vasco da Gama'),P('بارتولوميو دياز في رحلة 1488','Bartolomeu Dias on his 1488 voyage'),P('كولومبوس في رحلة الكاريبي','Columbus on his Caribbean voyage'),P('دار دياز حول الرأس؛ أكمل دا غاما الطريق إلى الهند لاحقًا.','Dias rounded the Cape; da Gama later completed the route to India.')));
add('french-revolution','الثورة الفرنسية','French Revolution','cause',P('تفاعلت أزمة مالية وامتيازات اجتماعية ومطالب سياسية وأزمة معيشة. مرّت الثورة بمراحل متغيرة؛ إعلان الحقوق لم يعنِ تطبيق المساواة على الجميع فورًا.','Financial crisis, social privileges, political demands and subsistence pressures interacted. The Revolution changed through several phases; declaring rights did not immediately make everyone equal.'),[E(1789,'اقتحام الباستيل','Storming of the Bastille','أصبح 14 تموز رمزًا للثورة على السلطة الملكية.','14 July became a symbol of revolution against royal authority.'),E(1792,'إلغاء الملكية','Monarchy abolished','ألغى المؤتمر الوطني الملكية في أيلول.','The National Convention abolished the monarchy in September.'),E(1799,'انقلاب برومير','Brumaire coup','صعد بونابرت إلى السلطة وانتهى حكم الإدارة.','Bonaparte took power and the Directory ended.')],[P('أزمة الدولة المالية وعدم المساواة في الامتيازات والضرائب','State financial crisis and unequal privileges and taxation')],[P('تغيير نظام الحكم وطرح حقوق المواطنة مع صراعات واستثناءات','Changes in government and claims to citizenship amid conflict and exclusions')],['france','coup'],A('أي تفسير لا يختزل الثورة في سبب واحد؟','Which explanation avoids reducing the Revolution to one cause?',P('تفاعل أزمة مالية واجتماعية وسياسية','Interaction of financial, social and political crises'),P('وقعت بسبب اختراع واحد فقط','It resulted from just one invention'),P('بدأت بسبب هزيمة واترلو في 1815','It began because of Waterloo in 1815'),P('واترلو لاحقة؛ تساعد الأسباب المتعددة على فهم الأزمة دون جعل النتيجة حتمية.','Waterloo came later; multiple causes explain the crisis without making its outcome inevitable.')));
add('napoleon','نابليون بونابرت','Napoleon Bonaparte','timeline',P('جمع نابليون بين إصلاح إداري وقانوني وحكم سلطوي وحروب توسعية. ندرس هذه الأبعاد معًا بدل اختزاله في بطل أو معركة واحدة.','Napoleon combined administrative and legal reform with authoritarian rule and expansionist war. These dimensions should be studied together rather than reduced to one hero or battle.'),[E(1799,'الاستيلاء على السلطة','Seizure of power','أنهى انقلاب برومير حكم الإدارة وأقام القنصلية.','The Brumaire coup ended the Directory and established the Consulate.'),E(1804,'القانون المدني والتتويج','Civil Code and coronation','صدر القانون المدني وتوّج نابليون إمبراطورًا.','The Civil Code was issued and Napoleon became emperor.'),E(1815,'واترلو ونهاية الحكم','Waterloo and end of rule','انتهت عودته القصيرة إلى الحكم بعد الهزيمة.','His brief return to power ended after defeat.')],[P('عدم الاستقرار السياسي وصعود قائد عسكري ناجح','Political instability and the rise of a successful military commander')],[P('إصلاحات قانونية وإدارية وآثار حروب واسعة','Legal-administrative reforms and consequences of extensive wars')],['napoleon','coup'],A('أي وصف يوازن جوانب حكم نابليون؟','Which description balances aspects of Napoleon’s rule?',P('إصلاحات قانونية مع سلطة مركزية وحروب','Legal reforms alongside centralized power and war'),P('حكم بلا حروب أو توسع','Rule without war or expansion'),P('إلغاء كل القوانين والإدارة','Abolition of all law and administration'),P('وجود إصلاحات لا يلغي الحكم السلطوي أو أضرار الحروب.','Reform does not erase authoritarian rule or the harm caused by war.')));
add('ottoman-early','الدولة العثمانية حتى نهاية القرن الثامن عشر','Ottoman Empire to the eighteenth century','timeline',P('توسعت الدولة العثمانية من الأناضول إلى إمبراطورية متعددة الشعوب. تغيرت قوتها وإدارتها وعلاقاتها؛ لا يفسر تاريخها الطويل خط صعود ثم انهيار بسيط.','The Ottoman state expanded from Anatolia into a multiethnic empire. Its power, administration and relationships changed; a simple rise-and-fall line cannot explain its long history.'),[E(1453,'فتح القسطنطينية','Conquest of Constantinople','أصبحت المدينة مركزًا إمبراطوريًا عثمانيًا.','The city became an Ottoman imperial centre.'),E(1517,'ضم مصر','Conquest of Egypt','أنهى الفتح السلطنة المملوكية المستقلة.','The conquest ended the independent Mamluk sultanate.'),E(1789,'تولي سليم الثالث','Selim III becomes sultan','ارتبط عهده بمحاولات إصلاح عسكري وإداري.','His reign was associated with military and administrative reform efforts.')],[P('قوة عسكرية وتحالفات وإدارة موارد وأراضٍ','Military power, alliances and management of resources and territories')],[P('إدارة مجتمعات متعددة وربط مراكز تجارية وسياسية','Government of diverse communities and connections among commercial and political centres')],['islam','egypt'],A('أي مدينة أصبحت مركز الحكم بعد فتح 1453؟','Which city became the imperial centre after its 1453 conquest?',P('القسطنطينية','Constantinople'),P('بغداد العباسية عند تأسيسها','Abbasid Baghdad at its foundation'),P('قرطبة الأموية','Umayyad Córdoba'),P('أصبحت القسطنطينية عاصمة عثمانية؛ الاسم الحديث الشائع هو إسطنبول.','Constantinople became the Ottoman capital; Istanbul is the commonly used modern name.')));
S.egyptModern={label:'National Army Museum · Egypt and Sudan',url:'https://www.nam.ac.uk/explore/egypt-and-sudan'};
S.outbreak={label:'Imperial War Museums · Outbreak of the First World War',url:'https://www.iwm.org.uk/history/first-world-war/outbreak'};
S.reformModern={label:'Cambridge University Press · Tanzimat 1839–1876',url:'https://www.cambridge.org/core/books/abs/history-of-the-ottoman-empire-and-modern-turkey/era-of-modern-reform-the-tanzimat-18391876/E8ED362843054F6484972A5DB866FB2E'};
const industrialEvents=[E(1769,'براءة اختراع واط','Watt’s patent','سجّل واط براءة تحسين المحرك البخاري بالمكثف المنفصل.','Watt patented improvements using a separate condenser.'),E(1825,'سكة ستوكتون ودارلنغتون','Stockton and Darlington Railway','مثّلت خطوة في توسع النقل بالسكك الحديدية.','This was a milestone in the expansion of railway transport.'),E(1830,'سكة ليفربول ومانشستر','Liverpool and Manchester Railway','ربطت السكك مراكز تجارية وصناعية.','Railways linked commercial and industrial centres.')];
const nationalEvents=[E(1848,'ثورات أوروبا','European revolutions','تداخلت مطالب قومية وليبرالية واجتماعية واختلفت نتائجها.','National, liberal and social demands overlapped, with differing outcomes.'),E(1861,'إعلان مملكة إيطاليا','Kingdom of Italy proclaimed','خطوة رئيسية في التوحيد؛ لم تُضم روما حتى 1870.','A major unification milestone; Rome was not incorporated until 1870.'),E(1871,'إعلان الإمبراطورية الألمانية','German Empire proclaimed','أُعلن التوحيد بقيادة بروسيا بعد حروب واتفاقات سياسية.','Unification under Prussian leadership followed wars and political agreements.')];
const ottomanEvents=[E(1839,'خط كلخانة','Gülhane Edict','افتتح مرحلة التنظيمات ووعود إصلاح الحكم والحقوق.','It opened the Tanzimat era with promises to reform government and rights.'),E(1856,'مرسوم الإصلاح','Reform Edict','أكد إصلاحات تتعلق بوضع رعايا الدولة، ومنهم غير المسلمين.','It reaffirmed reforms affecting Ottoman subjects, including non-Muslims.'),E(1876,'الدستور العثماني','Ottoman constitution','صدر الدستور الأول؛ لم يؤدِّ إلى حياة دستورية متصلة بلا انقطاع.','The first constitution was issued; constitutional government did not continue uninterrupted.')];
add('industrial','الثورة الصناعية','Industrial Revolution','cause',P('غيّرت المكننة والطاقة وتنظيم المصانع الإنتاج والعمل. بدأ التحول في بريطانيا ثم انتشر بوتيرة متفاوتة، مع نمو المدن ومخاطر العمل وعدم المساواة.','Mechanization, energy and factory organization changed production and work. Starting in Britain, the transition spread unevenly, bringing urban growth, dangerous work and inequality.'),industrialEvents,[P('توفر رأس المال والطاقة والمعرفة والأسواق والعمل','Access to capital, energy, knowledge, markets and labour')],[P('إنتاج أكبر ونقل أسرع وتحوّل ظروف العمل والسكن','Greater output, faster transport and changing working and living conditions')],['steam','industrial'],A('لماذا لا يفسّر اختراع واحد الثورة الصناعية كاملة؟','Why cannot one invention explain the whole Industrial Revolution?',P('لأن الطاقة والاستثمار والعمل والأسواق تفاعلت','Energy, investment, labour and markets interacted'),P('لأن المصانع لم تستعمل آلات','Factories did not use machines'),P('لأن التغيير وقع في كل الدول في اليوم نفسه','Every country changed on the same day'),P('كانت عملية طويلة شملت التكنولوجيا والمؤسسات والناس.','It was a long process involving technology, institutions and people.')));
add('nationalism','القومية','Nationalism','society',P('تربط القومية الانتماء إلى أمة بمطالب سياسية، مثل الوحدة أو الاستقلال. قد تعتمد على لغة وذاكرة ومؤسسات مشتركة، لكنها ليست شعورًا ثابتًا متطابقًا لدى الجميع.','Nationalism connects national belonging to political claims such as unity or independence. Shared language, memory and institutions can matter, but people do not all experience it identically.'),nationalEvents,[P('انتشار الطباعة والتعليم والمشاركة السياسية','Expansion of print, education and political participation')],[P('حركات توحيد واستقلال، وأحيانًا إقصاء وصراع','Unification and independence movements, sometimes also exclusion and conflict')],['national'],A('أي مطلب يمثل مشروع توحيد قومي؟','Which demand represents national unification?',P('جمع دول صغيرة في دولة قومية واحدة','Uniting smaller states into one national state'),P('زيادة محصول مزرعة فقط','Only increasing one farm’s harvest'),P('اختراع محرك جديد دون هدف سياسي','Inventing an engine without a political aim'),P('التوحيد هدف سياسي يختلف عن مجرد تقدم تقني أو اقتصادي.','Unification is a political aim, distinct from technical or economic improvement.')));
const imperialEvents=[E(1869,'افتتاح قناة السويس','Suez Canal opens','ازدادت أهمية الطريق البحري بين المتوسط والبحر الأحمر.','The maritime route between the Mediterranean and Red Sea gained importance.'),E(1882,'الاحتلال البريطاني لمصر','British occupation of Egypt','تداخلت المصالح المالية والاستراتيجية مع التدخل العسكري.','Financial and strategic interests intersected with military intervention.'),E(1884,'بدء مؤتمر برلين','Berlin Conference begins','ناقشت القوى الأوروبية قواعد توسعها في أفريقيا دون تمثيل الشعوب الأفريقية.','European powers discussed rules for expansion in Africa without representation of African peoples.',P('1884–1885','1884–1885'))];
add('imperialism','الإمبريالية','Imperialism','cause',P('الإمبريالية توسيع نفوذ دولة على مجتمعات أخرى بوسائل عسكرية أو سياسية أو اقتصادية. قد تتخذ شكل استعمار مباشر أو نفوذ دون ضم رسمي.','Imperialism extends a state’s power over other societies through military, political or economic means. It can involve direct colonization or influence without formal annexation.'),imperialEvents,[P('المنافسة الاستراتيجية والموارد والأسواق وتبريرات عنصرية','Strategic rivalry, resources, markets and racist justifications')],[P('فقدان سيادة واستغلال ومقاومة محلية','Loss of sovereignty, exploitation and local resistance')],['berlin','colonial','egyptModern'],A('هل تحتاج الإمبريالية دائمًا إلى ضم رسمي؟','Does imperialism always require formal annexation?',P('لا؛ قد تمارس نفوذًا اقتصاديًا أو سياسيًا','No; it can exercise economic or political control'),P('نعم؛ لا يوجد أي نفوذ دون ضم','Yes; influence without annexation is impossible'),P('هي تعني التجارة المتساوية فقط','It means only trade between equals'),P('يميّز المفهوم بين أشكال متعددة من السيطرة غير المتكافئة.','The concept includes several forms of unequal control.')));
add('colonialism','الاستعمار','Colonialism','society',P('الاستعمار إخضاع أرض وسكان لسلطة خارجية، وقد يشمل الاستيطان. ندرس الإدارة والاستغلال والمقاومة وأصوات السكان، ولا نختزله في رواية المستعمِر.','Colonialism subjects territory and people to outside rule and can include settlement. Study administration, exploitation, resistance and local voices, not only the colonizer’s account.'),imperialEvents,[P('السعي للسيطرة على الأرض والموارد وطرق التجارة','Attempts to control territory, resources and trade routes')],[P('تغيير المؤسسات والاقتصاد ومقاومة السيطرة','Changes to institutions and economies, and resistance to control')],['colonial','berlin','egyptModern'],A('لماذا نقرأ مصادر من السكان الخاضعين للاستعمار؟','Why read sources from colonized communities?',P('لفهم تجاربهم ومقاومتهم ومقارنة وجهات النظر','To understand their experiences and resistance and compare perspectives'),P('لأن مصدرًا واحدًا يروي كل شيء','Because one source tells everything'),P('لحذف كل خلاف بين الروايات','To remove every difference between accounts'),P('تنويع المصادر يتيح فحص السلطة والتحيز والتجارب المختلفة.','Diverse sources help examine power, bias and different experiences.')));
add('europe19','أوروبا في القرن التاسع عشر','Nineteenth-century Europe','timeline',P('شهد القرن التاسع عشر التصنيع والثورات والتوحيد القومي والتوسع الإمبريالي. لم يحدث التغير بالتساوي ولم تنفصل السياسة عن المجتمع والاقتصاد.','The nineteenth century saw industrialization, revolutions, national unification and imperial expansion. Change was uneven, and politics interacted with society and the economy.'),[E(1815,'مؤتمر فيينا','Congress of Vienna','أُعيد تنظيم التوازن الأوروبي بعد حروب نابليون.','European power relations were reorganized after the Napoleonic wars.'),nationalEvents[0],nationalEvents[2]],[P('تفاعل تغير الاقتصاد والمطالب السياسية والنزاعات الدولية','Interaction of economic change, political demands and international conflict')],[P('دول جديدة ونقاشات حول الحقوق وتمثيل السكان','New states and debates over rights and representation')],['national'],A('أي عبارة تصف القرن دون تعميم؟','Which statement avoids overgeneralizing the century?',P('تغيرت مناطق أوروبا بسرعات ومسارات مختلفة','European regions changed at different speeds and in different ways'),P('كل السكان حصلوا على الحقوق نفسها عام 1815','Everyone gained identical rights in 1815'),P('انتهت كل الحروب بعد مؤتمر فيينا','All wars ended after the Congress of Vienna'),P('لا تعني مرحلة تاريخية واحدة تجربة اجتماعية موحدة.','A historical period does not imply one uniform social experience.')));
const warEvents=[E(1914,'اندلاع الحرب','War breaks out','تحولت أزمة البلقان إلى حرب واسعة خلال تموز وآب.','The Balkan crisis expanded into a major war in July and August.'),E(1917,'دخول الولايات المتحدة الحرب','United States enters the war','أعلنت الولايات المتحدة الحرب على ألمانيا في نيسان.','The United States declared war on Germany in April.'),E(1918,'هدنة الجبهة الغربية','Western Front armistice','أوقفت هدنة 11 تشرين الثاني القتال على الجبهة الغربية؛ لم تكن كل التسويات قد اكتملت.','The 11 November armistice stopped Western Front fighting; the settlements were not yet complete.')];
add('wwi','الحرب العالمية الأولى','First World War','timeline',P('كانت حربًا عالمية بين 1914 و1918 شاركت فيها إمبراطوريات وشعوب من قارات متعددة. أثرت على المدنيين والجنود والعمل والاقتصاد، لا على الجبهات وحدها.','The 1914–1918 war involved empires and peoples across continents. It affected civilians, soldiers, work and economies, not only battlefronts.'),warEvents,[P('منافسة دولية وتحالفات وتسليح وأزمة 1914','International rivalry, alliances, armaments and the 1914 crisis')],[P('خسائر بشرية هائلة وانهيار إمبراطوريات وتغيرات سياسية','Immense human losses, collapsing empires and political change')],['ww1','outbreak'],A('لماذا توصف الحرب بأنها عالمية؟','Why is the war described as global?',P('شاركت قوى وشعوب وجبهات من قارات متعددة','Powers, peoples and fronts across continents were involved'),P('وقعت في مدينة واحدة فقط','It took place in only one city'),P('لأن كل دول العالم شاركت بالطريقة نفسها','Every country participated identically'),P('العالمية لا تعني مشاركة متطابقة لكل بلد.','Global scope does not mean identical participation by every country.')));
add('wwi-causes','أسباب الحرب العالمية الأولى','Causes of the First World War','cause',P('نميّز عوامل بعيدة مثل التنافس والتحالفات والتسليح عن شرارة اغتيال سراييفو. قرارات القادة خلال أزمة تموز وسّعت الحرب؛ لم تكن النتيجة آلية محتومة.','Distinguish long-term rivalry, alliances and armaments from the Sarajevo assassination as a trigger. Leaders’ decisions during the July Crisis expanded the war; the outcome was not automatic.'),[nationalEvents[2],E(1907,'التقارب البريطاني الروسي','Anglo-Russian agreement','عزز التقارب اصطفافات القوى الأوروبية.','The agreement strengthened European diplomatic alignments.'),E(1914,'اغتيال سراييفو وأزمة تموز','Sarajevo assassination and July Crisis','أثار الاغتيال أزمة دبلوماسية تلتها تعبئة وإعلانات حرب.','The assassination triggered a diplomatic crisis followed by mobilization and declarations of war.')],[P('التنافس الإمبريالي والتحالفات والمخاوف العسكرية','Imperial rivalry, alliances and military anxieties')],[P('انتقال أزمة محلية إلى صراع واسع بقرارات متعاقبة','Expansion from local crisis to wider conflict through successive decisions')],['outbreak','ww1'],A('ما الفرق بين الشرارة والعوامل البعيدة؟','How does a trigger differ from long-term factors?',P('الشرارة حادث مباشر؛ العوامل تراكمات سبقت الأزمة','A trigger is an immediate event; factors accumulated before the crisis'),P('كلاهما تاريخ توقيع الهدنة','Both mean the date of the armistice'),P('الشرارة تلغي دور كل القرارات','A trigger removes the role of every decision'),P('التفريق يساعد في تفسير التعقيد بدل نسبة الحرب إلى حادث واحد فقط.','The distinction explains complexity rather than attributing war to just one event.')));
add('wwi-events','أحداث الحرب العالمية الأولى','Events of the First World War','timeline',P('نقارن الجبهات والتوقيت بدل اعتبار الحرب معركة واحدة. الخنادق والبحر والتعبئة الصناعية وحركة الجيوش كانت أجزاء مترابطة من صراع طويل.','Compare fronts and timing rather than treating the war as one battle. Trenches, naval war, industrial mobilization and army movements were linked parts of a prolonged conflict.'),[E(1915,'حملة غاليبولي','Gallipoli campaign','حاول الحلفاء فتح طريق عبر المضائق العثمانية ولم يحققوا هدفهم.','The Allies tried unsuccessfully to open a route through the Ottoman straits.'),E(1916,'معركتا فردان والسوم','Verdun and the Somme','ارتبطت المعركتان باستنزاف وخسائر كبيرة على الجبهة الغربية.','Both battles involved attrition and heavy losses on the Western Front.'),warEvents[2]],[P('محاولات كسر الجمود والوصول إلى أهداف استراتيجية','Attempts to break stalemate and reach strategic objectives')],[P('استنزاف بشري ومادي وضغط على المجتمعات','Human and material attrition and pressure on societies')],['ww1','middle'],A('ما المقصود بحرب الاستنزاف؟','What does a war of attrition involve?',P('إضعاف قدرة الخصم تدريجيًا بخسائر مستمرة','Gradually weakening an opponent through continuing losses'),P('حسم كل الحرب دون خسائر في يوم','Settling the whole war without losses in one day'),P('غياب الصناعة والإمدادات عن الحرب','Industry and supplies playing no role'),P('يركز الاستنزاف على قدرة الجيوش والمجتمعات على مواصلة الحرب.','Attrition concerns the ability of armies and societies to sustain the war.')));
add('wwi-results','نتائج الحرب العالمية الأولى','Consequences of the First World War','cause',P('انتهى القتال الرئيسي قبل اكتمال التسويات السياسية. ترافقت الخسائر والديون والنزوح مع انهيار إمبراطوريات وظهور دول ونزاعات جديدة.','Major fighting ended before political settlements were complete. Losses, debt and displacement accompanied imperial collapse, new states and new disputes.'),[warEvents[2],E(1919,'معاهدة فرساي','Treaty of Versailles','فرضت التسوية مع ألمانيا شروطًا إقليمية وعسكرية ومالية.','The settlement with Germany imposed territorial, military and financial conditions.'),E(1920,'بدء عمل عصبة الأمم','League of Nations begins work','بدأت المنظمة عملها بهدف التعاون ومنع الحروب مع قيود على فعاليتها.','The organization began work to support cooperation and prevent war, with limits to its effectiveness.')],[P('حجم الدمار وهزيمة قوى مركزية ومطالب سياسية متعارضة','Destruction, defeat of Central Powers and conflicting political demands')],[P('تسويات غير مستقرة ومؤسسات دولية جديدة','Unstable settlements and new international institutions')],['peace','paris'],A('هل الهدنة ومعاهدة السلام الشيء نفسه؟','Are an armistice and a peace treaty the same?',P('لا؛ الهدنة توقف القتال والمعاهدة تعالج شروط التسوية','No; an armistice stops fighting and a treaty addresses settlement terms'),P('نعم؛ لا فرق قانوني أو سياسي بينهما','Yes; there is no legal or political distinction'),P('الهدنة تعني بدء الحرب','An armistice means starting a war'),P('هدنة 1918 سبقت معاهدة فرساي عام 1919.','The 1918 armistice preceded the 1919 Treaty of Versailles.')));
add('peace1919','اتفاقيات السلام سنة 1919','Peace settlements of 1919','timeline',P('لم تكن تسوية ما بعد الحرب معاهدة واحدة لكل الأطراف. جمعت المفاوضات مصالح المنتصرين ومطالب قومية ومبدأ تقرير المصير الذي طُبق بصورة انتقائية.','The postwar settlement was not one treaty for every party. Negotiations combined victors’ interests, national claims and a selectively applied principle of self-determination.'),[E(1919.01,'افتتاح مؤتمر باريس','Paris Peace Conference opens','بدأ المؤتمر في كانون الثاني لمناقشة تسويات ما بعد الحرب.','The conference opened in January to discuss postwar settlements.',P('كانون الثاني 1919','January 1919')),E(1919.06,'توقيع فرساي','Versailles signed','وُقعت المعاهدة مع ألمانيا في 28 حزيران.','The treaty with Germany was signed on 28 June.',P('حزيران 1919','June 1919')),E(1919.09,'سان جرمان','Saint-Germain','وُقعت معاهدة مع النمسا في أيلول.','A treaty with Austria was signed in September.',P('أيلول 1919','September 1919'))],[P('الرغبة في الأمن والتعويضات وإعادة تنظيم الحدود','Demands for security, reparations and reorganization of borders')],[P('حدود ومؤسسات جديدة مع خلافات على شرعية التسويات','New borders and institutions amid disputes over the settlements’ legitimacy')],['paris','peace'],A('مع أي دولة وُقعت معاهدة فرساي؟','With which state was the Treaty of Versailles signed?',P('ألمانيا','Germany'),P('النمسا في سان جرمان','Austria at Saint-Germain'),P('بريطانيا بوصفها الطرف المهزوم','Britain as the defeated party'),P('فرساي تخص التسوية مع ألمانيا؛ وُقعت معاهدات أخرى مع دول مهزومة أخرى.','Versailles addressed Germany; other defeated states had other treaties.')));
add('middle19','الشرق الأوسط في القرن التاسع عشر','Nineteenth-century Middle East','routes',P('تداخل الإصلاح المحلي والتجارة العالمية والتدخل الأوروبي. تمثل مصر وقناة السويس حالة دراسة، ولا تختصران تجارب كل مجتمعات المنطقة.','Local reform, global trade and European intervention interacted. Egypt and the Suez Canal offer a case study, not a summary of every regional society.'),[ottomanEvents[0],imperialEvents[0],imperialEvents[1]],[P('تغير التجارة والديون ومحاولات تحديث الدولة','Changing trade, debt and attempts at state reform')],[P('ارتباط اقتصادي أوسع وتدخل أجنبي ومقاومة','Wider economic integration, foreign intervention and resistance')],['egyptModern','tanzimat'],A('لماذا اكتسبت قناة السويس أهمية استراتيجية؟','Why did the Suez Canal gain strategic importance?',P('قصّرت الطريق البحري بين أوروبا وآسيا','It shortened the sea route between Europe and Asia'),P('ألغت كل التجارة البحرية','It ended all maritime trade'),P('ربطت المحيط الهادئ بالأطلسي','It connected the Pacific and Atlantic'),P('تصل القناة المتوسط بالبحر الأحمر وتؤثر في التجارة والنقل العسكري.','The canal links the Mediterranean and Red Sea and affects trade and military transport.')));
add('ottoman19','الدولة العثمانية في القرن التاسع عشر','Nineteenth-century Ottoman Empire','society',P('حاولت التنظيمات إصلاح الجيش والإدارة والقانون وعلاقة الدولة برعاياها. نميز النصوص المعلنة عن التطبيق المتفاوت والصراعات على السلطة.','The Tanzimat sought to reform the army, administration, law and relations with subjects. Distinguish declared reforms from uneven implementation and struggles over power.'),ottomanEvents,[P('ضغوط عسكرية ومالية ومطالب بتقوية مؤسسات الدولة','Military and fiscal pressures and attempts to strengthen state institutions')],[P('مؤسسات وقوانين جديدة ونقاشات حول الحقوق والمواطنة','New institutions and laws and debates over rights and citizenship')],['tanzimat','reformModern'],A('لماذا لا يكفي قراءة مرسوم إصلاح للحكم على أثره؟','Why is reading a reform decree insufficient to judge its impact?',P('يجب فحص التطبيق والاختلاف بين المناطق والجماعات','Implementation and differences across regions and groups must be examined'),P('لأن المراسيم لا تتعلق بالتاريخ','Decrees are unrelated to history'),P('لأن الإعلان يضمن التطبيق الكامل فورًا','Announcement guarantees immediate full implementation'),P('الوثيقة تثبت ما أُعلن؛ يحتاج أثره إلى أدلة إضافية.','A document establishes what was announced; its effects require further evidence.')));
add('middle-wwi','الشرق الأوسط حتى نهاية الحرب العالمية الأولى','Middle East through the end of the First World War','timeline',P('غيّرت الحرب الحكم والحياة اليومية في المنطقة. تقاطعت خطط القوى الكبرى مع حركات محلية، ورافقتها مجاعة ونزوح وخسائر مدنية؛ لم تُحسم كل الحدود في 1918.','War changed government and daily life across the region. Great-power plans intersected with local movements amid famine, displacement and civilian losses; not all borders were settled in 1918.'),[E(1914,'دخول الدولة العثمانية الحرب','Ottoman entry into the war','دخلت الدولة الحرب إلى جانب القوى المركزية في خريف 1914.','The empire entered the war on the Central Powers’ side in autumn 1914.'),E(1916,'اتفاق سايكس بيكو','Sykes–Picot Agreement','اتفاق سري بريطاني فرنسي حول مناطق نفوذ مقترحة؛ ليس رسمًا نهائيًا لكل الحدود الحالية.','A secret Anglo-French agreement proposed zones of influence; it was not the final map of all present borders.'),E(1918,'هدنة مودروس','Armistice of Mudros','أوقفت الهدنة مشاركة الدولة العثمانية في الحرب في نهاية تشرين الأول.','The armistice ended Ottoman participation in the war at the end of October.')],[P('تحالفات الحرب ومصالح القوى وحركات سياسية محلية','Wartime alliances, great-power interests and local political movements')],[P('انتهاء الحكم العثماني في مناطق عربية وبدء صراع على التسوية','End of Ottoman rule in Arab territories and struggles over the settlement')],['ww1','middle'],A('هل رسم سايكس بيكو وحده كل حدود الشرق الأوسط الحالية؟','Did Sykes–Picot alone draw every current Middle Eastern border?',P('لا؛ تبعته قرارات وتسويات وصراعات أخرى','No; further decisions, settlements and conflicts followed'),P('نعم؛ بقي كل خط بلا تغيير','Yes; every line remained unchanged'),P('لم توجد قوى محلية في المنطقة','There were no local actors in the region'),P('كان الاتفاق جزءًا من عملية أوسع لا خريطة نهائية لكل الحدود.','The agreement was part of a wider process, not a final map of every border.')));
export function historyLesson(title){const name=typeof title==='string'?title:title?.title;return HISTORY_LESSONS.find(x=>x.title===name)||null}
export function historyQuestion(topic,difficulty='medium',n=0,language='ar'){const d=historyLesson(topic);if(!d)return null;const i=Math.abs(Math.trunc(Number(n)||0)),q=d.questions[i%d.questions.length],ix=language==='en'?1:0,options=q.options.map(p=>p[ix]),answer=options[q.answer],offset=(i+d.id.length)%options.length;return {type:'mcq',prompt:q.prompt[ix],options:[...options.slice(offset),...options.slice(0,offset)],answer,explanation:q.explanation[ix],points:10,subject:'history',difficulty}}
export function historyQuestions(topic,language='ar'){const d=historyLesson(topic);return d?d.questions.map((_,i)=>historyQuestion(topic,'medium',i,language)):[]}
